CREATE SEQUENCE "OPCH_DocNum_seq" START WITH 2001;

-- A/P invoices (purchases): header, the same structure as OINV.
CREATE TABLE "OPCH" (
    "DocEntry"   INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DocNum"     INT            NOT NULL DEFAULT nextval('"OPCH_DocNum_seq"') UNIQUE,
    "DocType"    VARCHAR(1)     NOT NULL DEFAULT 'I' CHECK ("DocType" IN ('I', 'S')),
    "CANCELED"   VARCHAR(1)     NOT NULL DEFAULT 'N' CHECK ("CANCELED" IN ('Y', 'N', 'C')),
    "DocStatus"  VARCHAR(1)     NOT NULL DEFAULT 'O' CHECK ("DocStatus" IN ('O', 'C')),
    "DocDate"    DATE           NOT NULL,
    "DocDueDate" DATE           NOT NULL,
    "CardCode"   VARCHAR(15)    NOT NULL REFERENCES "OCRD" ("CardCode"),
    "CardName"   VARCHAR(200),
    "DocTotal"   NUMERIC(19, 6) NOT NULL DEFAULT 0,
    "PaidToDate" NUMERIC(19, 6) NOT NULL DEFAULT 0,
    "OwnerCode"  INT            REFERENCES "OHEM" ("empID"),
    "SlpCode"    INT            NOT NULL DEFAULT -1,
    "GroupNum"   INT            NOT NULL DEFAULT -1,
    "Installmnt" INT            NOT NULL DEFAULT 1,
    "Comments"   VARCHAR(254)
);

-- A/P invoices: rows, the same structure as INV1.
CREATE TABLE "PCH1" (
    "DocEntry"   INT            NOT NULL REFERENCES "OPCH" ("DocEntry"),
    "LineNum"    INT            NOT NULL,
    "LineStatus" VARCHAR(1)     NOT NULL DEFAULT 'O' CHECK ("LineStatus" IN ('O', 'C')),
    "ItemCode"   VARCHAR(50)    NOT NULL REFERENCES "OITM" ("ItemCode"),
    "Dscription" VARCHAR(200),
    "Quantity"   NUMERIC(19, 6) NOT NULL,
    "Price"      NUMERIC(19, 6) NOT NULL,
    "LineTotal"  NUMERIC(19, 6) NOT NULL,
    "WhsCode"    VARCHAR(8)     NOT NULL,
    "TaxCode"    VARCHAR(8),
    "VatGroup"   VARCHAR(8),
    PRIMARY KEY ("DocEntry", "LineNum")
);
